def count_people(image_path, person_labels=['baseball', 'basket'], threshold=0.35):
    detection = {}  # Tracks detected objects with their bounding box and confidence score
    for img_label in person_labels:
        img = Object_Detector_Tool.execute(image=image_path, labels=[img_label], threshold=threshold)
        boxes = [box for box in img['output_type'][0]['bbox'] if box[2] >= threshold]
        if boxes:
            boxes = [box[2] / 100 for box in boxes]
            detection[img_label] = {'bbox': boxes, 'confidence': img['output_type'][0]['confidence'][0]}
            # This is an example of how to add empty padding around detected objects
            for label in person_labels:
                boxes = [bbox / 100 for box in detection[label]['bbox']]
                detection[label]['bbox'] = [(0,0)] + boxes
                detection[label][' confidence'] = (0.35 / 2, 0.35) + detection[label]['confidence'][0] 
        else:
            detection[img_label] = {'bbox': [0,0], ' confidence': list()}

    return detection

